const stories={tree:['POKOK · LIVING LIGHT','Wake the canopy.','Tap a tree to awaken the lights climbing its trunk. Nearby lanterns answer with a wave of light. Tap again to let it rest.'],solar:['SURIA · STORED SUNSHINE','Sunlight, saved for the night.','These imagined solar flowers collect energy by day and share it with the garden after dark. Tap to awaken a pool of light beneath the petals.'],ruin:['HUTAN · A FOREST THRESHOLD','The forest remembers.','Moss-covered arches mark the passage between gardens. These fantasy ruins are imagined, rather than a reconstruction of a historical Malay site. Tap to send a soft gong tone through the trees.'],house:['RUMAH · A HOME FOR TOMORROW','Old wisdom. New energy.','Raised timber homes and steep roofs inspire this imagined kampung. Here, solar roofs and planted verandas form a possible future. Tap another home to add a note.'],lantern:['ANYAMAN · INTERLACED LIGHT','A little light, woven together.','These geometric lanterns imagine woven forms as living light. Your tap rings a synthetic chime; the surrounding lights answer the low frequencies in your sound.'],garden:['KEBUN · THE LIVING GARDEN','Let the garden answer.','A speculative tropical garden that blooms when you touch it. Higher frequencies stir the canopy; sound energy gently changes your pace.'],about:['SERI · FIELD NOTES','A forest that listens.','An endless, interactive Malay-inspired solarpunk reverie. Drag to look; tap houses, woven lanterns, and roadside flowers. Use the microphone or your own music. Audio stays in your browser. This is an imagined world with original plucked and gong-like synthesized sound, not a traditional gamelan performance or archival recording or a reconstruction of a specific village.']};function show(type){const s=stories[type];$('cardTag').textContent=s[0];$('cardTitle').textContent=s[1];$('cardText').textContent=s[2];$('card').hidden=false}$('about').onclick=$('help').onclick=()=>show('about');$('closeCard').onclick=()=>$('card').hidden=true;$('home').onclick=e=>{e.preventDefault();$('intro').hidden=false;$('journey').hidden=true;entered=false;document.body.classList.remove('entered')};
